// Lv13에서 1.0491%가 나온다 — 게임은 1.05%다.
//
//   값(%) = floor(레벨 × 계수) / 100
//
// 세 계수 모두 실제 응답과 맞춰 확인했다:
//   공격력 Lv30 → 1.10%,  추가 피해 Lv13 → 1.05%,  보스 피해 Lv10 → 0.83%
const ARK_GRID_GEM_EFFECTS = [
  { key: "attack", label: "공격력", group: "공격력", factor: 3.667 },
  { key: "additional", label: "추가 피해", group: "추가 피해", factor: 8.0834 },
  { key: "boss", label: "보스 피해", group: "보스 피해", factor: 8.3334 },
];

function arkGridGemDamage(key, level) {
  const effect = ARK_GRID_GEM_EFFECTS.find(item => item.key === key);
  if (!effect) return 0;
  const value = clamp(Math.round(readNumber(level)), 0, GEM_MAX_LEVEL);
  return Math.floor(value * effect.factor) / 100;
}

