// 품질 0에서도 10%이고 100에서 30%다.
const WEAPON_QUALITY_MAX = 100;

function weaponQualityDamage(quality) {
  const q = Math.min(WEAPON_QUALITY_MAX, Math.max(0, Number(quality) || 0));
  return 0.002 * q * q + 10;
}

